interface Handler {
  setNext(h: Handler): void
  handle(req: string): boolean
}

class AuthHandler implements Handler { next?: Handler; setNext(h: Handler){this.next = h}
  handle(req: string){ if (req === 'auth') return true; return this.next?.handle(req) ?? false }
}

// client composes handlers: auth.setNext(extra); auth.handle('auth')

class HandlerA { handle(req:string){ /* ... */ return false } }
class HandlerB { handle(req:string){ /* ... */ return true } }

class RequestProcessor {
  chain:any
  constructor(){ this.chain = new HandlerA(); this.chain.next = new HandlerB() }
  process(req:string){ return this.chain.handle(req) }
}

